    nw_casino: ['{a} won {m} {x}. The casino manager is sweating.', '{a} walked out of the casino {m} richer, {x}.', 'That lucky bastard {a} pulled {m} {x}.', '{a} cleaned out {m} {x}. Security is watching him now.', '{a} made {m} {x} and bought everyone a round. Just kidding, he bought fuck all.', 'Smells like cheating: {a} won {m} {x}.'],
    nw_casinoLoss: ['{a} lost {m} {x} and walked home.', '{a} left {m} {x}. The casino says thanks.', 'That dumb fuck {a} went gambling {x} and came out poorer than he already was: {m} down.', '{a} buried {m} {x}. His wife doesn’t know yet.', 'That sucker {a} handed {m} to the casino {x}. Thanks, come again.', '{a} lost {m} {x} and then asked for bus money.', 'There go {m} of {a}’s, {x}. Some guys never learn.'],
    hl_lucky_t: 'Lucky of the day: {a}', hl_lucky: ['{a} won {m} in one play at the casino {d}. Security is watching him.', '{a} broke the bank {d}: {m} on a single play.'],
