    nw_job: ['{a} hit "{x}" and walked off with {m}.', '{a} cleaned out "{x}": {m} in the pocket.', 'Another one for {a}: "{x}", {m}.', 'That bastard {a} did "{x}" and legged it with {m}.', '{a} walked in, did "{x}", walked out with {m}. Nobody saw shit.', '"{x}": {m} into {a}’s pocket. The police are still looking for the car.', '{a} is cashing in: "{x}", {m}.'],
