    nw_spree: ['{a} pulled {n} jobs in a row and took {m}. No breaks.', '{a} spent the afternoon robbing: {n} jobs, {m}.', '{a} doesn’t sleep: {n} jobs back to back, {m}.', '{n} jobs in a row by {a}. He took {m} and the city got lighter.', '{a} did {n} jobs without stopping for a piss: {m}.'],
