    nw_lux: ['{a} bought {x}. Some people just can\'t hide their money.', '{a} is showing off {x} all over town.', 'That show-off {a} bought {x}. More money than shame.', '{a} is parading {x} around town. Practically begging to get mugged.', 'Purchase of the day: {x}, for {a}. That money sure as hell isn’t clean.'],
    nw_beat: ['That dumb fuck {b} got beaten up by {a}.', '{a} beat the shit out of that bastard {b}, who left in an ambulance.', '{a} smashed {b}\'s face in. There are teeth on the pavement.', '{b} took such a beating from {a} he’s talking in a higher voice now.', '{a} gave {b} a proper hiding. They’re still looking for one tooth.', 'That bastard {b} played the tough guy and {a} folded him in half.', '{a} wrecked {b}. The hospital asked if it was a truck.', '{b} got hit so many times by {a} that he respects everybody now.'],
